final class CatalogueBrowser
{
    static BankCatalogue.Choice choose(Component parent,List<BankCatalogue.Choice> choices,String initial,java.util.function.Predicate<BankCatalogue.Choice> deletePreset)
    {
        JPanel panel=new JPanel(new BorderLayout(0,8)); JTextField search=new JTextField(initial);
        JComboBox<String> kind=new JComboBox<>(new String[]{"Everything","Categories","Presets","Wiki setups","Custom presets","Saved groups"});
        JPanel top=new JPanel(new BorderLayout(6,0)); top.add(search,BorderLayout.CENTER); top.add(kind,BorderLayout.EAST); panel.add(top,BorderLayout.NORTH);
        DefaultListModel<BankCatalogue.Choice> rows=new DefaultListModel<>(); JList<BankCatalogue.Choice> list=new JList<>(rows);
        list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION); list.setVisibleRowCount(14);
        boolean[] chosen={false};
        Runnable activate=() -> {
            if(list.getSelectedValue()==null) return;
            chosen[0]=true;
            Window window=SwingUtilities.getWindowAncestor(panel); if(window instanceof JDialog) window.dispose();
        };
        list.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mouseClicked(java.awt.event.MouseEvent e) {
            int index=list.locationToIndex(e.getPoint());
            if(e.getClickCount()==2 && index>=0 && list.getCellBounds(index,index).contains(e.getPoint())) activate.run();
        }});
        list.getInputMap().put(KeyStroke.getKeyStroke("ENTER"),"choose");
        list.getActionMap().put("choose",new AbstractAction() { public void actionPerformed(java.awt.event.ActionEvent e) { activate.run(); } });
        JButton remove=new JButton("Delete saved preset…"); remove.setEnabled(false);
        list.addListSelectionListener(e -> { BankCatalogue.Choice value=list.getSelectedValue(); list.setToolTipText(value==null?null:value.name);
            remove.setEnabled(value!=null && value.kind==BankCatalogue.Kind.CUSTOM_PRESET); });
        panel.add(new JScrollPane(list),BorderLayout.CENTER);
        JPanel footer=new MarkerForm();
        footer.add(new JLabel("<html>Type to search; approximate spellings and CoX/ToB/ToA work.<br>Choose a result to review its items before adding groups.<br>Saved custom presets can be deleted here; existing groups stay.</html>"));
        footer.add(remove); panel.add(footer,BorderLayout.SOUTH);
        Runnable refresh=() -> {
            rows.clear(); int selectedKind=kind.getSelectedIndex();
            List<BankCatalogue.Choice> filtered=new java.util.ArrayList<>();
            for(BankCatalogue.Choice choice:choices) if(selectedKind==0 || choice.kind.ordinal()==selectedKind-1) filtered.add(choice);
            for(BankCatalogue.Choice choice:BankCatalogue.search(filtered,search.getText(),150)) rows.addElement(choice);
        };
        remove.addActionListener(e -> {
            BankCatalogue.Choice selected=list.getSelectedValue();
            if(selected!=null && selected.kind==BankCatalogue.Kind.CUSTOM_PRESET && deletePreset.test(selected)) {
                choices.remove(selected); refresh.run();
            }
        });
        javax.swing.Timer timer=new javax.swing.Timer(150,e -> refresh.run()); timer.setRepeats(false);
        search.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) { timer.restart(); } public void removeUpdate(DocumentEvent e) { timer.restart(); } public void changedUpdate(DocumentEvent e) { timer.restart(); }
        });
        kind.addActionListener(e -> refresh.run()); refresh.run();
        try { boolean accepted=MarkerDialogs.confirm(parent,panel,"Categories and presets",760,540); return accepted || chosen[0]?list.getSelectedValue():null; }
        finally { timer.stop(); }
    }
}

package com.windowmarkers;

import java.awt.Color;
import java.util.*;

/** Apply reviewed classifications without discarding other uses or resetting existing styles. */
final class CategoryGroups
{
    static final class Result
    {
        final List<Marker> selected=new ArrayList<>();
        int added, existing, skipped, limited;
    }
    static Result add(List<Marker> markers,Map<String,List<AutoCategories.Item>> groups,String preset,
        boolean includeGrouped,Color defaultColor,int limit)
    {
        Result result=new Result();
        Set<Integer> assigned=new HashSet<>(); List<Color> colors=new ArrayList<>();
        for(Marker marker:markers) {
            if(marker.linked()) for(int id:marker.linkedItemIds) assigned.add(id);
            colors.add(marker.borderArgb==null?defaultColor:new Color(marker.borderArgb,true));
        }
        for(Map.Entry<String,List<AutoCategories.Item>> entry:groups.entrySet()) {
            int[] requested=entry.getValue().stream().mapToInt(i -> i.id).distinct().sorted().toArray();
            Marker existing=markers.stream().filter(m -> m.linked() && entry.getKey().equals(m.category)
                && preset.equals(m.preset) && Arrays.equals(requested,Arrays.stream(m.linkedItemIds).distinct().sorted().toArray())).findFirst().orElse(null);
            if(existing!=null) { result.existing++; result.selected.add(existing); continue; }
            int[] ids=Arrays.stream(requested).filter(id -> includeGrouped || !assigned.contains(id)).toArray();
            if(ids.length==0) { result.skipped++; continue; }
            if(markers.size()>=limit) { result.limited++; continue; }
            Marker marker=new Marker(0,0,48,36); marker.scrollWithItems=true; marker.linkedItemIds=ids;
            marker.label=MarkerPresentation.title(entry.getKey()); marker.labelOnce=true;
            marker.category=entry.getKey(); marker.preset=preset; marker.labelFont="Arial"; marker.labelSize=12;
            marker.labelPlacement=Marker.LabelPlacement.ABOVE; marker.style=WindowMarkersConfig.BorderStyle.PLAIN;
            Color color=MarkerPresentation.nextColor(colors); colors.add(color);
            marker.borderArgb=color.getRGB(); marker.backgroundArgb=new Color(color.getRed(),color.getGreen(),color.getBlue(),65).getRGB();
            markers.add(marker); result.selected.add(marker); result.added++;
            for(int id:ids) assigned.add(id);
        }
        return result;
    }
}

package com.windowmarkers;

import java.util.HashMap;
import java.util.Map;

/** Reviewed combat roles only; never a universal alias for utility, quests or clues. */
final class CombatEquivalence
{
    private static final Map<Integer,String> FAMILIES=new HashMap<>();
    private static final Map<Integer,Boolean> MAX_REQUIREMENTS=new HashMap<>();
    static
    {
        for (String resource:new String[]{"combat-equivalences.tsv","cosmetic-combat-equivalences.tsv"})
        for (String[] row:ItemTaxonomy.readRows(resource,3))
        {
            int id=Integer.parseInt(row[0]);
            if (FAMILIES.put(id,row[1])!=null || (!row[2].equals("true") && !row[2].equals("false")))
            { throw new IllegalStateException("Invalid combat equivalence: "+id); }
            MAX_REQUIREMENTS.put(id,Boolean.parseBoolean(row[2]));
        }
    }
    static String familyName(AutoCategories.Item item)
    { return FAMILIES.getOrDefault(item.id,ItemVariantState.familyName(item)); }
    static boolean requiresMaxedSkills(AutoCategories.Item item)
    { return MAX_REQUIREMENTS.getOrDefault(item.id,false); }
    static boolean matches(AutoCategories.Item item,String expected)
    {
        String family=familyName(item);
        if (family.equals("imbued ancient cape") && (expected.equals("god capes") || expected.equals("imbued god cape")))
        { return true; }
        return ItemTaxonomy.matches(family,expected);
    }
    static boolean matchesAny(AutoCategories.Item item,String... expected)
    { for (String name:expected) { if (matches(item,name)) { return true; } } return false; }
}

package com.windowmarkers;

import java.util.*;

/** Separate account/profile-scoped templates; applying copies markers, never moves bank items. */
final class CustomPresets
{
    static final int LIMIT=50;
    List<Preset> presets=new ArrayList<>();
    static final class Preset
    {
        String name;
        boolean bankView, groupBySlot;
        List<Marker> groups=new ArrayList<>();
        @Override public String toString() { return name; }
    }
    void normalize()
    {
        if(presets==null) presets=new ArrayList<>();
        Set<String> names=new HashSet<>();
        presets.removeIf(p -> p==null || p.name==null || p.name.trim().isEmpty());
        if(presets.size()>LIMIT) presets=new ArrayList<>(presets.subList(0,LIMIT));
        for(Preset p:presets)
        {
            p.name=p.name.trim().substring(0,Math.min(60,p.name.trim().length()));
            if(p.groups==null) p.groups=new ArrayList<>();
            p.groups.removeIf(m -> m==null || !m.valid() || !m.linked() || m.linkedItemIds.length>4000);
            if(p.groups.size()>250) p.groups=new ArrayList<>(p.groups.subList(0,250));
            for(Marker group:p.groups) group.linkedItemIds=Arrays.stream(group.linkedItemIds).filter(id -> id>=0).distinct().toArray();
            p.groups.removeIf(m -> !m.linked());
        }
        presets.removeIf(p -> !names.add(p.name.toLowerCase(Locale.ROOT)) || p.groups.isEmpty());
    }
}

