/** Proven restrictions only. A blank reason is not proof that every quest/unlock is satisfied. */
final class GeRequirements
{
    private static final List<String[]> REQUIREMENTS=ItemTaxonomy.readRows("raid-wear-requirements.tsv",8);
    private static final Skill[] SKILLS={Skill.ATTACK,Skill.STRENGTH,Skill.DEFENCE,Skill.RANGED,Skill.MAGIC,Skill.PRAYER,Skill.HITPOINTS};
    private final int[] levels;
    private final boolean allMaxed;
    private final Boolean ancientRings;
    static void prepare() { /* initialize bundled data on the catalogue worker */ }
    GeRequirements(int[] levels,boolean allMaxed,Boolean ancientRings)
    { this.levels=levels.clone();this.allMaxed=allMaxed;this.ancientRings=ancientRings; }
    static GeRequirements capture(Client client,Boolean ancientRings)
    {
        int[] levels=new int[SKILLS.length];for(int i=0;i<levels.length;i++) levels[i]=client.getRealSkillLevel(SKILLS[i]);
        boolean maxed=Arrays.stream(Skill.values()).filter(s->s!=Skill.OVERALL).allMatch(s->client.getRealSkillLevel(s)>=99);
        return new GeRequirements(levels,maxed,ancientRings);
    }
    boolean reviewed(ItemCatalogueIndex.Item item)
    { return REQUIREMENTS.stream().anyMatch(row->CombatEquivalence.matches(item.fact,row[0])); }
    String locked(ItemCatalogueIndex.Item item)
    {
        List<String> missing=new ArrayList<>();
        if(CombatEquivalence.requiresMaxedSkills(item.fact) && !allMaxed) missing.add("99 in every skill");
        if(CombatEquivalence.matchesAny(item.fact,"ultor ring","magus ring","venator ring","bellator ring") && Boolean.FALSE.equals(ancientRings))
            missing.add("Desert Treasure II completion");
        for(String[] row:REQUIREMENTS) if(CombatEquivalence.matches(item.fact,row[0])) {
            for(int i=0;i<SKILLS.length;i++) if(levels[i]<Integer.parseInt(row[i+1])) missing.add(row[i+1]+" "+SKILLS[i].getName());
            break;
        }
        return String.join(", ",missing);
    }
}

package com.windowmarkers;

import net.runelite.api.FontTypeFace;
import net.runelite.api.widgets.Widget;

/** Fits annotations inside the native GE result row without moving its click target. */
final class GeResultLabel
{
    static String format(Widget label, String name, String details)
    {
        if (details.isEmpty()) return name;
        FontTypeFace font = label.getFont();
        int width = label.getWidth();
        if (font == null || width <= 0) return name;
        int lineHeight = label.getLineHeight() > 0 ? label.getLineHeight() : font.getBaseline();
        // Unusual layouts may only have room for the name. Details remain in the tooltip.
        if (lineHeight <= 0 || label.getHeight() < lineHeight * 2) return fit(name, font, width);
        return fit(name, font, width) + "<br>" + fit(details, font, width);
    }

    static String fit(String text, FontTypeFace font, int width)
    {
        text = text.replace("<br>", " ");
        if (font.getTextWidth(text) <= width) return text;
        String ending = "...</col></u></str>";
        if (font.getTextWidth(ending) > width) return "";
        StringBuilder prefix = new StringBuilder();
        // Preserve the native search highlighting; never cut through a markup tag.
        for (int i = 0; i < text.length();) {
            int end = text.charAt(i) == '<' ? text.indexOf('>', i) + 1 : i + 1;
            if (end <= i) end = i + 1;
            String token = text.substring(i, end);
            if (font.getTextWidth(prefix.toString() + token + ending) > width) break;
            prefix.append(token);
            i = end;
        }
        return prefix + ending;
    }
}

package com.windowmarkers;

import java.util.*;

/** Identity-based edits keep filtered-out groups and saved item variants intact. */
final class GroupEdits
{
    static int[] union(Collection<Marker> groups)
    { return groups.stream().filter(Marker::linked).flatMapToInt(m -> Arrays.stream(m.linkedItemIds)).distinct().toArray(); }

    static boolean reorder(List<Marker> all,List<Marker> visible,List<Marker> moving,int dropIndex)
    {
        if(visible.isEmpty() || moving.isEmpty() || dropIndex<0 || dropIndex>visible.size()
            || !all.containsAll(visible) || !visible.containsAll(moving)
            || new HashSet<>(visible).size()!=visible.size()) return false;
        List<Marker> actual=new ArrayList<>();
        for(Marker marker:all) if(visible.contains(marker)) actual.add(marker);
        if(!actual.equals(visible)) return false;
        List<Marker> ordered=new ArrayList<>(visible);
        List<Marker> picked=new ArrayList<>(); int before=0;
        for(int i=0;i<visible.size();i++) if(moving.contains(visible.get(i)))
        { picked.add(visible.get(i)); if(i<dropIndex) before++; }
        ordered.removeAll(picked); ordered.addAll(dropIndex-before,picked);
        if(ordered.equals(visible)) return false;
        int index=0;
        for(int i=0;i<all.size();i++) if(visible.contains(all.get(i))) all.set(i,ordered.get(index++));
        return true;
    }
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.*;

/** Pure geometry for matching visible items without changing game widgets. */
final class ItemAnchors
{
    static final class Cell
    {
        final int id;
        final Rectangle icon, grid;
        Cell(int id, Rectangle icon)
        {
            this.id=id; this.icon=new Rectangle(icon);
            grid=new Rectangle(icon);
            // The native bank slot has 12px horizontal and 4px vertical spacing.
            if (grid.width <= 36) { grid.x-=6; grid.width+=12; }
            if (grid.height <= 32) { grid.y-=2; grid.height+=4; }
        }
    }

    static int[] enclosed(Rectangle selection, List<Cell> cells, Rectangle viewport)
    {
        return cells.stream().filter(c -> viewport.contains(c.icon.getCenterX(),c.icon.getCenterY())
            && selection.contains(c.icon.getCenterX(),c.icon.getCenterY())).mapToInt(c -> c.id).distinct().toArray();
    }

    static Rectangle snap(Rectangle selection, List<Cell> cells)
    {
        if (cells.isEmpty()) { return selection; }
        Rectangle grid=cells.get(0).grid;
        int x=grid.x+Math.floorDiv(selection.x-grid.x,grid.width)*grid.width;
        int y=grid.y+Math.floorDiv(selection.y-grid.y,grid.height)*grid.height;
        int right=grid.x+Math.floorDiv(selection.x+selection.width-1-grid.x,grid.width)*grid.width+grid.width;
        int bottom=grid.y+Math.floorDiv(selection.y+selection.height-1-grid.y,grid.height)*grid.height+grid.height;
        return new Rectangle(x,y,right-x,bottom-y);
    }

    static List<Rectangle> regions(int[] ids, List<Cell> cells)
    {
        Set<Integer> wanted=new HashSet<>(); for (int id : ids) { wanted.add(id); }
        List<Rectangle> result=new ArrayList<>();
        for (Cell cell : cells)
        {
            if (wanted.contains(cell.id) && !result.contains(cell.grid)) { result.add(new Rectangle(cell.grid)); }
        }
        result.sort(Comparator.comparingInt((Rectangle r)->r.y).thenComparingInt(r->r.x));
        // Merge only full shared edges: unrelated slots and holes stay unmarked.
        boolean changed;
        do
        {
            changed=false;
            outer: for (int i=0;i<result.size();i++) for (int j=i+1;j<result.size();j++)
            {
                Rectangle a=result.get(i), b=result.get(j);
                boolean horizontal=a.y==b.y && a.height==b.height && (a.x+a.width==b.x || b.x+b.width==a.x);
                boolean vertical=a.x==b.x && a.width==b.width && (a.y+a.height==b.y || b.y+b.height==a.y);
                if (horizontal || vertical)
                { result.set(i,a.union(b)); result.remove(j); changed=true; break outer; }
            }
        } while (changed);
        return result;
    }
}

