import java.awt.*;
import java.awt.event.KeyEvent;
import javax.swing.*;

/** Scroll only the form; keep confirmation controls outside its viewport. */
final class MarkerDialogs
{
    static Color chooseColor(Component parent,String title,Color initial)
    {
        JColorChooser chooser=new JColorChooser(initial);
        return confirm(parent,chooser,title,700,540) ? chooser.getColor() : null;
    }
    static boolean confirm(Component parent,JComponent content,String title,int width,int height)
    {
        Window owner=parent==null ? null : SwingUtilities.getWindowAncestor(parent);
        JDialog dialog=new JDialog(owner,title,Dialog.ModalityType.APPLICATION_MODAL);
        boolean[] accepted={false};
        JButton ok=new JButton("OK"),cancel=new JButton("Cancel");
        ok.addActionListener(e -> { accepted[0]=true; dialog.dispose(); });
        cancel.addActionListener(e -> dialog.dispose());
        JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));
        buttons.add(ok); buttons.add(cancel);
        JScrollPane scroll=new JScrollPane(content,JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        scroll.getVerticalScrollBar().setUnitIncrement(20);
        scroll.setMinimumSize(new Dimension(0,0));
        JPanel root=new JPanel(new BorderLayout(0,10));
        root.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));
        root.add(scroll,BorderLayout.CENTER); root.add(buttons,BorderLayout.SOUTH);
        dialog.setContentPane(root);
        dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        dialog.setResizable(true);
        dialog.getRootPane().setDefaultButton(ok);
        dialog.getRootPane().registerKeyboardAction(e -> dialog.dispose(),KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE,0),JComponent.WHEN_IN_FOCUSED_WINDOW);
        GraphicsConfiguration configuration=owner==null ? dialog.getGraphicsConfiguration() : owner.getGraphicsConfiguration();
        Rectangle screen=configuration.getBounds();
        Insets insets=Toolkit.getDefaultToolkit().getScreenInsets(configuration);
        Rectangle usable=new Rectangle(screen.x+insets.left,screen.y+insets.top,
            screen.width-insets.left-insets.right,screen.height-insets.top-insets.bottom);
        Rectangle bounds=initialBounds(usable,width,height);
        dialog.setMinimumSize(new Dimension(Math.min(320,bounds.width),Math.min(200,bounds.height)));
        dialog.setBounds(bounds);
        try { dialog.setVisible(true); return accepted[0]; }
        finally { dialog.dispose(); }
    }
    static Rectangle initialBounds(Rectangle screen,int width,int height)
    {
        int w=Math.min(width,Math.max(1,screen.width-24)),h=Math.min(height,Math.max(1,screen.height-24));
        return new Rectangle(screen.x+(screen.width-w)/2,screen.y+(screen.height-h)/2,w,h);
    }
}

package com.windowmarkers;

import java.awt.*;
import javax.swing.*;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;

/** A width-constrained column: natural control heights and wrapping text. */
final class MarkerForm extends JPanel implements Scrollable
{
    MarkerForm() { super(null); }

    private int height(Component child, int width)
    {
        if (child instanceof JTextArea)
        {
            child.setSize(width, Short.MAX_VALUE);
        }
        if (child instanceof JLabel)
        {
            View html=(View)((JLabel)child).getClientProperty(BasicHTML.propertyKey);
            if (html!=null)
            {
                html.setSize(width,0);
                return (int)Math.ceil(html.getPreferredSpan(View.Y_AXIS));
            }
        }
        return child.getPreferredSize().height;
    }

    @Override public Dimension getPreferredSize()
    {
        Insets in=getInsets();
        int width=getWidth()>0 ? getWidth() : 420;
        int y=in.top;
        for(Component child:getComponents()) if(child.isVisible())
        { y+=height(child,Math.max(1,width-in.left-in.right))+4; }
        return new Dimension(width,y+in.bottom);
    }

    @Override public void doLayout()
    {
        Insets in=getInsets(); int y=in.top, width=Math.max(1,getWidth()-in.left-in.right);
        for(Component child:getComponents()) if(child.isVisible())
        {
            int h=height(child,width); child.setBounds(in.left,y,width,h); y+=h+4;
        }
    }
    @Override public Dimension getMinimumSize() { return new Dimension(0,0); }
    @Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
    @Override public boolean getScrollableTracksViewportWidth() { return true; }
    @Override public boolean getScrollableTracksViewportHeight() { return false; }
    @Override public int getScrollableUnitIncrement(Rectangle r,int axis,int direction) { return 20; }
    @Override public int getScrollableBlockIncrement(Rectangle r,int axis,int direction) { return Math.max(20,r.height-20); }
}

package com.windowmarkers;

import java.util.ArrayDeque;
import java.util.Deque;

final class MarkerHistory
{
    private String current;
    private final Deque<String> undo=new ArrayDeque<>(), redo=new ArrayDeque<>();
    void reset(String value) { current=value; undo.clear(); redo.clear(); }
    void record(String value)
    {
        if (value.equals(current)) { return; }
        if (current != null) { undo.addLast(current); if (undo.size()>50) { undo.removeFirst(); } }
        current=value; redo.clear();
    }
    String undo()
    {
        if (undo.isEmpty()) { return null; }
        redo.addLast(current); current=undo.removeLast(); return current;
    }
    String redo()
    {
        if (redo.isEmpty()) { return null; }
        undo.addLast(current); current=redo.removeLast(); return current;
    }
    boolean matches(String value) { return value.equals(current); }
}

