/** Per-role substitutions only; never removes an item from its other raid uses. */
final class RaidGearFilter
{
    private static final List<String[]> RANKS=ItemTaxonomy.readRows("raid-ranks.tsv",5);
    private static final List<String[]> REQUIREMENTS=ItemTaxonomy.readRows("raid-wear-requirements.tsv",8);
    static void filter(AutoCategories.Preset preset,Map<String,List<AutoCategories.Item>> groups,int[] levels,Map<Integer,String> exclusions)
    { filter(preset,groups,levels,false,exclusions); }
    static void filter(AutoCategories.Preset preset,Map<String,List<AutoCategories.Item>> groups,int[] levels,boolean ancientRingsUnlocked,Map<Integer,String> exclusions)
    { filter(preset,groups,levels,ancientRingsUnlocked,false,exclusions); }
    static void filter(AutoCategories.Preset preset,Map<String,List<AutoCategories.Item>> groups,int[] levels,boolean ancientRingsUnlocked,boolean allSkillsMaxed,Map<Integer,String> exclusions)
    {
        if(preset!=AutoCategories.Preset.CHAMBERS_OF_XERIC && preset!=AutoCategories.Preset.THEATRE_OF_BLOOD && preset!=AutoCategories.Preset.TOMBS_OF_AMASCUT) { return; }
        String raid=RaidRecommendations.raid(preset);
        for(Map.Entry<String,List<AutoCategories.Item>> group:groups.entrySet())
        {
            String style=group.getKey().contains("Magic") ? "Magic" : group.getKey().contains("Ranged") ? "Ranged" : group.getKey().endsWith("Melee") ? "Melee" : "";
            if(style.isEmpty()) { continue; }
            List<AutoCategories.Item> candidates=new ArrayList<>(group.getValue());
            group.getValue().removeIf(item -> {
                if(protectedUse(item)) { return false; }
                for(String[] lower:RANKS)
                {
                    if(!lower[0].equals(raid) || !lower[1].equals(style) || !CombatEquivalence.matches(item,lower[4])) { continue; }
                    for(String[] higher:RANKS)
                    {
                        if(!higher[0].equals(raid) || !higher[1].equals(style) || !higher[2].equals(lower[2]) || Integer.parseInt(higher[3])>=Integer.parseInt(lower[3])) { continue; }
                        for(AutoCategories.Item upgrade:candidates)
                        {
                            if(upgrade.id==item.id || protectedUse(upgrade) || !CombatEquivalence.matches(upgrade,higher[4]) || !sameRole(lower[2],item,upgrade) || !canWear(upgrade,levels,ancientRingsUnlocked,allSkillsMaxed)) { continue; }
                            String reason=group.getKey()+": "+item.name+" → "+upgrade.name+" (Wiki "+lower[2].toLowerCase(Locale.ROOT)+" ranking)";
                            exclusions.merge(item.id,reason,(a,b) -> a+"; "+b); return true;
                        }
                    }
                }
                return false;
            });
        }
        groups.values().removeIf(List::isEmpty);
    }
    private static boolean canWear(AutoCategories.Item item,int[] levels,boolean ancientRingsUnlocked,boolean allSkillsMaxed)
    {
        if(CombatEquivalence.requiresMaxedSkills(item) && !allSkillsMaxed) { return false; }
        if(ItemTaxonomy.matchesAny(item,"ultor ring","magus ring","venator ring","bellator ring")) { return ancientRingsUnlocked; }
        for(String[] row:REQUIREMENTS)
        {
            if(!CombatEquivalence.matches(item,row[0])) { continue; }
            for(int i=0;i<7;i++) { if((i<levels.length ? levels[i] : 1)<Integer.parseInt(row[i+1])) { return false; } }
            return true;
        }
        return false;
    }
    private static boolean sameRole(String slot,AutoCategories.Item lower,AutoCategories.Item higher)
    {
        String n=ItemTaxonomy.baseName(CombatEquivalence.familyName(lower));
        if(slot.contains("weapon"))
        {
            // Explicit substitutions, not a blanket comparison of a row containing multiple loadout roles.
            if(n.equals("abyssal whip")) { return CombatEquivalence.matchesAny(higher,"abyssal tentacle","blade of saeldor"); }
            if(n.equals("trident of the seas")) { return CombatEquivalence.matchesAny(higher,"trident of the swamp","sanguinesti staff"); }
            if(n.equals("warped sceptre")) { return CombatEquivalence.matchesAny(higher,"trident of the seas","trident of the swamp","sanguinesti staff"); }
            if(n.equals("rune crossbow")) { return CombatEquivalence.matchesAny(higher,"dragon crossbow","armadyl crossbow","zaryte crossbow","dragon hunter crossbow"); }
            return false;
        }
        if(slot.equals("Ring"))
        {
            return (n.equals("berserker ring (i)") && CombatEquivalence.matches(higher,"ultor ring"))
                || (n.equals("seers ring (i)") && CombatEquivalence.matches(higher,"magus ring"));
        }
        if(slot.equals("Shield"))
        {
            return (n.equals("dragon defender") && CombatEquivalence.matches(higher,"avernic defender"))
                || (n.equals("elidinis' ward") && CombatEquivalence.matches(higher,"elidinis' ward (f)"));
        }
        return true;
    }
    private static boolean protectedUse(AutoCategories.Item item)
    {
        String n=ItemTaxonomy.baseName(CombatEquivalence.familyName(item));
        return ItemVariantState.needsActivityReview(item)
            || ItemTaxonomy.equipmentSet(n)!=null || n.startsWith("virtus ") || n.startsWith("bloodbark ")
            || n.startsWith("oathplate ") || n.equals("serpentine helm") || n.contains("blood fury")
            || n.startsWith("mixed hide ");
    }
}

package com.windowmarkers;

import java.util.*;

/** Explicit per-activity membership from the cited Wiki tables, plus reviewed supply lists. */
final class RaidRecommendations
{
    private static final List<String[]> EQUIPMENT=new ArrayList<>();
    private static final List<String[]> ROOMS=ItemTaxonomy.readRows("raid-layout-rooms.tsv",2);
    static
    {
        EQUIPMENT.addAll(ItemTaxonomy.readRows("raid-equipment.tsv",3));
        EQUIPMENT.addAll(ItemTaxonomy.readRows("raid-context-equipment.tsv",3));
    }

    static Map<String,List<AutoCategories.Item>> suggest(AutoCategories.Preset preset,List<AutoCategories.Item> items)
    {
        String raid=raid(preset), prefix=raid.equals("cox") ? "CoX" : raid.equals("tob") ? "ToB" : "ToA";
        Map<String,List<AutoCategories.Item>> groups=new LinkedHashMap<>();
        for (String[] row : EQUIPMENT)
        {
            if (!row[0].equals(raid)) { continue; }
            for (AutoCategories.Item item : items)
            {
                if (!CombatEquivalence.matches(item,row[2])) { continue; }
                // Learner alternatives repeated in a main-role table use that role's group and filtering.
                if(row[1].startsWith("Learner") && EQUIPMENT.stream().anyMatch(other -> other[0].equals(raid)
                    && !other[1].startsWith("Learner") && CombatEquivalence.matches(item,other[2]))) { continue; }
                String group=row[1];
                if (ItemVariantState.needsActivityReview(item,group))
                { group=ItemVariantState.reviewGroup(item); }
                else if (isVoid(ItemVariantState.familyName(item)))
                { group=completeVoid(items) ? "Elite Void switches — choose helm for role" : "Incomplete Void set — review"; }
                else if (isCrystal(ItemVariantState.familyName(item)))
                { group=completeCrystal(items) ? "Crystal bow setup" : "Incomplete crystal setup — review"; }
                else if (raid.equals("tob") && group.equals("Magic")) { group="Magic switches — freezer role"; }
                else if (raid.equals("tob") && group.equals("Ranged")) { group="Ranged switches — ranger/Tbow use"; }
                // Keep combat role keys stable for the same-role upgrade filter.
                if (group.startsWith("Guardians tools") || group.startsWith("Special attacks"))
                { group=ItemVariantState.annotate(group,item); }
                AutoCategories.add(groups,prefix+" "+group,item);
            }
        }
        for (AutoCategories.Item item : items)
        {
            String supply=supplyGroup(raid,ItemVariantState.familyName(item));
            if (supply!=null)
            {
                if (ItemVariantState.needsActivityReview(item)) { supply=ItemVariantState.reviewGroup(item); }
                AutoCategories.add(groups,prefix+" "+supply,item);
            }
        }
        return groups;
    }

    static String raid(AutoCategories.Preset preset)
    { return preset==AutoCategories.Preset.CHAMBERS_OF_XERIC ? "cox" : preset==AutoCategories.Preset.THEATRE_OF_BLOOD ? "tob" : "toa"; }

    /** Prefer a documented room or utility role over the item's equipment slot. */
    static String layoutGroup(String activity,AutoCategories.Item item)
    {
        String raid=activity.startsWith("Chambers of Xeric")?"cox":activity.startsWith("Theatre of Blood")?"tob":activity.startsWith("Tombs of Amascut")?"toa":"";
        if(raid.isEmpty() || ItemVariantState.needsActivityReview(item)) return "";
        Set<String> rooms=new LinkedHashSet<>();String special="";
        for(String[] row:EQUIPMENT) if(row[0].equals(raid) && CombatEquivalence.matches(item,row[2]))
        {
            String role=row[1];
            if(role.equals("Melee") || role.equals("Magic") || role.equals("Ranged") || role.startsWith("Learner")) continue;
            if(role.startsWith("Special attacks")) special="Special attacks — strategy dependent";
            else rooms.add(role.replace("Guardians tools (room dependent)","Guardians — pickaxes"));
        }
        if(!rooms.isEmpty()) return String.join(" / ",rooms);
        String supply=supplyGroup(raid,ItemVariantState.familyName(item));
        return supply!=null?supply:special;
    }

    static Set<String> layoutGroups(String activity,AutoCategories.Item item)
    {
        Set<String> groups=new LinkedHashSet<>();
        if(ItemVariantState.needsActivityReview(item)) return groups;
        for(String[] row:ROOMS) {
            ActivitySetups.Setup setup=ActivitySetups.byId(row[0]);
            if(setup!=null && setup.activity.equals(activity) && setup.itemIds.contains(item.id)) {
                String label=row[1];
                if(label.equals("Guardians — pickaxes") && !"Tools".equals(ItemTaxonomy.weaponRole(CombatEquivalence.familyName(item))))
                    label="Guardians — defence-drain specials";
                groups.add(label);
            }
        }
        String utility=layoutGroup(activity,item);
        if(groups.isEmpty() && !utility.isEmpty()) groups.add(utility);
        return groups;
    }

    static String roomNote(String activity,String heading)
    {
        for(String[] row:ROOMS) if(row[1].equals(heading) || heading.equals("Guardians — defence-drain specials") && row[1].equals("Guardians — pickaxes")) {
            ActivitySetups.Setup setup=ActivitySetups.byId(row[0]);
            if(setup!=null && setup.activity.equals(activity)) return activity+" / "+setup.label+". "+setup.notes;
        }
        return "";
    }

    /** Discoverable names even when none of the relevant items are currently owned. */
    static Set<String> groups()
    {
        Set<String> result=new TreeSet<>();
        for(String raid:Arrays.asList("cox","tob","toa")) {
            String prefix=raid.equals("cox")?"CoX":raid.equals("tob")?"ToB":"ToA";
            Set<String> roles=new TreeSet<>();
            for(String[] row:EQUIPMENT) if(row[0].equals(raid)) {
                String role=row[1];
                if(raid.equals("tob") && role.equals("Magic")) role="Magic switches — freezer role";
                if(raid.equals("tob") && role.equals("Ranged")) role="Ranged switches — ranger/Tbow use";
                roles.add(role);
            }
            roles.addAll(Arrays.asList("Elite Void switches — choose helm for role","Incomplete Void set — review","Crystal bow setup","Incomplete crystal setup — review"));
            roles.addAll(Arrays.asList("Needs repair/charge — review","Check charges — review","Unverified item identity — review",
                "Activity restrictions — review","Check item use — review","Reduced function — review","Preparation needed — review","Check contents — review","Empty — review"));
            for(String name:Arrays.asList("saradomin brew","super restore","prayer potion","stamina potion","sanfew serum",
                "super combat potion","ranging potion","anglerfish","cooked karambwan","saturated heart","salve amulet (e)","salve amulet(ei)",
                "water rune","blood rune","air rune","antidote++","keris partisan of the sun","rune pouch")) {
                String group=supplyGroup(raid,name); if(group!=null) roles.add(group);
            }
            for(String role:roles) result.add(prefix+" "+role);
        }
        return result;
    }

    static String source(AutoCategories.Preset preset)
    {
        switch (preset)
        {
            case CHAMBERS_OF_XERIC: return "https://oldschool.runescape.wiki/w/Chambers_of_Xeric/Strategies";
            case THEATRE_OF_BLOOD: return "https://oldschool.runescape.wiki/w/Theatre_of_Blood/Strategies";
            case TOMBS_OF_AMASCUT: return "https://oldschool.runescape.wiki/w/Tombs_of_Amascut/Strategies";
            default: return "https://oldschool.runescape.wiki/w/Weapons/Types";
        }
    }

    static boolean defaultSelected(String group)
    { return !group.startsWith("Other") && !group.contains("review") && !group.contains("Incomplete") && !group.contains("Needs repair"); }

    private static boolean owns(List<AutoCategories.Item> items,String... names)
    { return items.stream().anyMatch(i -> !ItemVariantState.needsActivityReview(i) && ItemTaxonomy.matchesAny(i,names)); }

    private static boolean completeVoid(List<AutoCategories.Item> items)
    {
        return owns(items,"elite void top") && owns(items,"elite void robe") && owns(items,"void knight gloves")
            && owns(items,"void melee helm","void ranger helm","void mage helm");
    }

    private static boolean completeCrystal(List<AutoCategories.Item> items)
    { return owns(items,"crystal helm") && owns(items,"crystal body") && owns(items,"crystal legs") && owns(items,"bow of faerdhinen"); }

    private static boolean isVoid(String name)
    { String set=ItemTaxonomy.equipmentSet(name); return set!=null && set.startsWith("Void —"); }

    private static boolean isCrystal(String name)
    { String set=ItemTaxonomy.equipmentSet(name); return set!=null && set.startsWith("Crystal —"); }

    static String supplyGroup(String raid,String name)
    {
        String n=ItemTaxonomy.baseName(name);
        // Intentionally positive lists: no Drink/Eat inference, substring matches, or blanket potion/rune groups.
        if (raid.equals("tob"))
        {
            if (oneOf(n,"saradomin brew","super restore","prayer potion","stamina potion")) { return "Restoration supplies"; }
            if (oneOf(n,"super combat potion","divine super combat potion","ranging potion")) { return "Combat boosts — role/prepot"; }
            if (oneOf(n,"anglerfish")) { return "Food — overheal/Maiden"; }
            if (oneOf(n,"cooked karambwan")) { return "Food — combo eating"; }
            if (oneOf(n,"saturated heart","imbued heart")) { return "Magic boost — freezer role"; }
            if (oneOf(n,"salve amulet (e)","salve amulet(ei)","salve amulet (ei)")) { return "Bloat — undead melee"; }
            if (oneOf(n,"water rune","death rune","blood rune")) { return "Ice Barrage runes — Ancients/freezer"; }
        }
        else if (raid.equals("cox"))
        {
            if (oneOf(n,"saradomin brew","super restore","prayer potion")) { return "Restoration supplies"; }
            if (oneOf(n,"stamina potion")) { return "Stamina — solo Olm/running"; }
            if (oneOf(n,"sanfew serum")) { return "Poison protection — shamans"; }
            if (oneOf(n,"super combat potion","ranging potion")) { return "Combat boosts — layout/prepot"; }
            if (oneOf(n,"anglerfish")) { return "Food — pre-raid overheal"; }
            if (oneOf(n,"salve amulet(ei)","salve amulet (ei)")) { return "Mystics — no Shadow setup"; }
        }
        else if (raid.equals("toa"))
        {
            if (oneOf(n,"saradomin brew")) { return "Brews — excludes Dehydration"; }
            if (oneOf(n,"super restore","prayer potion","sanfew serum")) { return "Prayer/restoration supplies"; }
            if (oneOf(n,"super combat potion","divine super combat potion","ranging potion","divine ranging potion")) { return "Combat boosts — path/prepot"; }
            if (oneOf(n,"antidote++")) { return "Poison protection — path dependent"; }
            if (oneOf(n,"anglerfish")) { return "Food — pre-raid (On a Diet restricts eating)"; }
            if (oneOf(n,"saturated heart","imbued heart")) { return "Magic boost — pre-raid"; }
            if (oneOf(n,"keris partisan of the sun")) { return "Healing utility — needs special energy"; }
        }
        if (oneOf(n,"rune pouch","divine rune pouch","book of the dead")) { return "Spell supplies — choose spellbook"; }
        if (oneOf(n,"air rune","cosmic rune","blood rune")) { return "Thrall runes — Arceuus only"; }
        return null;
    }
    private static boolean oneOf(String name,String... names) { return Arrays.asList(names).contains(name); }
}

package com.windowmarkers;

import java.util.*;

/** Optional guide-tier qualifiers; never rewrites the player's native input. */
final class SearchQuery
{
    final String text;
    final Set<Integer> tiers;
    private SearchQuery(String text,Set<Integer> tiers) { this.text=text;this.tiers=Collections.unmodifiableSet(tiers); }
    static SearchQuery parse(String raw) {
        List<String> words=new ArrayList<>(); Set<Integer> tiers=new HashSet<>();
        for(String word:SearchText.normalize(raw).split(" +")) {
            // In food searches a number is HP per bite, not an equipment tier.
            if(SupplySearch.foodQuery(raw) && word.matches("[0-9]+")) { words.add(word);continue; }
            switch(word) {
                case "1": case "1st": case "first": case "bis": tiers.add(1);break;
                case "2": case "2nd": case "second": tiers.add(2);break;
                case "3": case "3rd": case "third": tiers.add(3);break;
                default:words.add(word);
            }
        }
        return new SearchQuery(String.join(" ",words),tiers);
    }
    boolean accepts(ItemCatalogueIndex.Rank rank) { return tiers.isEmpty() || rank!=null && tiers.contains(rank.tier); }
}

package com.windowmarkers;

import java.text.Normalizer;
import java.util.Locale;

/** Shared, bounded typo matching for names, categories and presets. */
final class SearchText
{
    static String normalize(String text)
    {
        return Normalizer.normalize(text==null ? "" : text,Normalizer.Form.NFKD)
            .replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replace("'","").replace("’","")
            .replaceAll("[^a-z0-9]+"," ").trim();
    }
    static int score(String text,String query)
    { return normalizedScore(normalize(text),normalize(query)); }
    static boolean containsWords(String text,String query) {
        for(String word:query.split(" +")) if(!text.contains(word)) return false;
        return true;
    }
    static String correctWholeWords(java.util.Set<String> vocabulary,String terms) {
        java.util.List<String> corrected=new java.util.ArrayList<>();
        for(String term:terms.split(" +")) {
            String replacement=term;
            if(term.length()>=4 && !vocabulary.contains(term)) {
                int allowed=term.length()<8?1:2,best=allowed+1; boolean tied=false;
                for(String candidate:vocabulary) {
                    if(Math.abs(candidate.length()-term.length())>allowed) continue;
                    int cost=distance(candidate,term);
                    if(cost<best) { best=cost;replacement=candidate;tied=false; }
                    else if(cost==best) tied=true;
                }
                if(best>allowed || tied) replacement=term;
            }
            corrected.add(replacement);
        }
        return String.join(" ",corrected);
    }
    static int normalizedScore(String text,String query)
    {
        if(query.isEmpty() || text.equals(query)) return 0;
        if(query.length()>256) return Integer.MAX_VALUE;
        if(text.startsWith(query)) return 1;
        if(text.contains(query)) return 2;
        int score=3;
        String[] words=text.split(" ");
        for(String needle:query.split(" "))
        {
            if(text.contains(needle)) continue;
            int allowed=needle.length()<4 ? 0 : needle.length()<8 ? 1 : 2;
            boolean match=false;
            for(String word:words) if(matchesWord(word,needle,allowed))
            { match=true; break; }
            if(!match) return Integer.MAX_VALUE;
            score+=2;
        }
        return score;
    }
    private static boolean matchesWord(String word,String needle,int allowed)
    {
        if(allowed==0) return false;
        // Search as the user types: a typo in an unfinished word should not make
        // its suggestions disappear until the final letters have been entered.
        for(int length=Math.max(1,needle.length()-allowed);length<=Math.min(word.length(),needle.length()+allowed);length++)
            if(distance(word.substring(0,length),needle)<=allowed) return true;
        return false;
    }
    static int distance(String a,String b)
    {
        int[][] d=new int[a.length()+1][b.length()+1];
        for(int i=0;i<=a.length();i++) d[i][0]=i;
        for(int j=0;j<=b.length();j++) d[0][j]=j;
        for(int i=1;i<=a.length();i++) for(int j=1;j<=b.length();j++)
        {
            d[i][j]=Math.min(d[i-1][j]+1,Math.min(d[i][j-1]+1,d[i-1][j-1]+(a.charAt(i-1)==b.charAt(j-1)?0:1)));
            if(i>1 && j>1 && a.charAt(i-1)==b.charAt(j-2) && a.charAt(i-2)==b.charAt(j-1))
                d[i][j]=Math.min(d[i][j],d[i-2][j-2]+1);
        }
        return d[a.length()][b.length()];
    }
}

package com.windowmarkers;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.*;
import net.runelite.client.game.ItemManager;

/** Repeated bank displays reference the existing stack and its existing actions. */
final class SetupInventoryWidgets
{
    private static final class Copy
    {
        final Widget widget,source,parent;
        final int itemId;
        Copy(Widget widget,Widget source,Widget parent,int itemId)
        { this.widget=widget;this.source=source;this.parent=parent;this.itemId=itemId; }
    }
    private final Map<Widget,Copy> copies=new IdentityHashMap<>();
    private final Map<MenuEntry,Copy> menus=new WeakHashMap<>();
    private Client client;
    void setClient(Client client) { this.client=client; }

    Widget add(Widget parent,Widget source,int exampleId,ItemManager manager)
    {
        int id=source==null?exampleId:source.getItemId();
        Widget widget=parent.createChild(-1,WidgetType.GRAPHIC);
        widget.setOriginalWidth(36);widget.setOriginalHeight(32);
        widget.setItemId(id);widget.setBorderType(1);
        if(source!=null)
        {
            widget.setItemQuantity(source.getItemQuantity());
            widget.setItemQuantityMode(source.getItemQuantityMode());
            widget.setOpacity(source.getOpacity());widget.setName(source.getName());
            String[] actions=source.getActions();
            if(actions!=null) for(int i=0;i<actions.length;i++) if(actions[i]!=null) widget.setAction(i,actions[i]);
            WidgetConfigNode config=client==null?null:client.getWidgetConfig(source);
            int mask=config==null?source.getClickMask():config.getClickMask();
            widget.setClickMask(mask & ~(WidgetConfig.DRAG|WidgetConfig.DRAG_ON|WidgetConfig.WIDGET_USE_TARGET));
            widget.setOnOpListener(source.getOnOpListener());
            widget.setHasListener(source.getOnOpListener()!=null);
        }
        else
        {
            var definition=manager.getItemComposition(id);
            widget.setName(definition==null?"Guide item":definition.getName());
            widget.setItemQuantity(1);widget.setItemQuantityMode(ItemQuantityMode.NEVER);
            widget.setOpacity(150);widget.setClickMask(0);
        }
        copies.put(widget,new Copy(widget,source,parent,id));
        return widget;
    }

    boolean preview(Widget widget) { Copy copy=copies.get(widget);return copy!=null && copy.source==null; }

    void menuAdded(MenuEntry menu)
    {
        menus.remove(menu);
        Copy copy=copies.get(menu.getWidget());
        if(copy==null || copy.source==null || menu.getParam1()!=InterfaceID.Bankmain.ITEMS
            || menu.getType()!=MenuAction.CC_OP && menu.getType()!=MenuAction.CC_OP_LOW_PRIORITY) return;
        // Rebind the already-existing action, before other plugins inspect it.
        // No action is invoked, and withdrawal quantity remains the user's choice.
        menu.setParam0(copy.source.getIndex());
        menus.put(menu,copy);
    }

    void clicked(MenuOptionClicked event,Client client)
    {
        Copy copy=menus.get(event.getMenuEntry());
        if(copy==null) return;
        ItemContainer bank=client.getItemContainer(InventoryID.BANK);
        int index=copy.source.getIndex();
        Item item=bank==null?null:bank.getItem(index);
        if(client.getWidget(InterfaceID.Bankmain.ITEMS)!=copy.parent || copy.parent.getChild(index)!=copy.source
            || copy.source.isSelfHidden() || copy.source.getItemId()!=copy.itemId
            || item==null || item.getId()!=copy.itemId || item.getQuantity()<=0)
            event.consume();
    }

    void clear()
    {
        Set<Widget> parents=Collections.newSetFromMap(new IdentityHashMap<>());
        for(Copy copy:copies.values()) parents.add(copy.parent);
        for(Widget parent:parents)
        {
            Widget[] children=parent.getChildren();if(children==null) continue;
            Widget[] remaining=children.clone();int length=remaining.length;
            // Remove only our exact widgets, preserving children another plugin replaced or appended.
            while(length>0 && copies.containsKey(remaining[length-1])) length--;
            for(int i=0;i<remaining.length;i++) if(copies.containsKey(remaining[i])) { remaining[i].setHidden(true);remaining[i]=null; }
            parent.setChildren(Arrays.copyOf(remaining,length));
        }
        copies.clear();
    }
}

