package com.windowmarkers;

import java.util.*;

/** One source equipment table and one source inventory, never a union of inventories. */
final class SetupLoadout
{
    static final class Field {
        final String name, note; final List<Integer> ids=new ArrayList<>();
        final boolean guideOnly;
        Field(String[] row) { this(row,false); }
        Field(String[] row,boolean guideOnly) { name=row[1]; note=row[3];this.guideOnly=guideOnly; for(String id:row[2].split(",")) if(!id.isEmpty()) ids.add(Integer.parseInt(id)); }
        int slot() { return name.matches("2h[0-9]*")?3:ItemCatalogueIndex.slot(name.replaceAll("[0-9]+$","")); }
        int order() { String number=name.replaceFirst("^2h","weapon").replaceAll("[^0-9]",""); return number.isEmpty()?0:Integer.parseInt(number); }
        boolean unconditional() { return note.isEmpty() || note.equals("Can function as hybrid armour, saving inventory space"); }
        boolean inventoryChoice() { return !guideOnly && (note.isEmpty() || note.startsWith("The Wiki chooses ") || note.startsWith("The Vale Totems magiclog variable ")); }
    }
    static final class Table {
        final String kind,context,style; final List<Field> fields=new ArrayList<>();
        Table(String[] row) { kind=row[1];context=row[2];style=row[3]; }
    }
    private static final Map<String,Table> TABLES=new LinkedHashMap<>();
    private static final Map<String,String> INVENTORY_PAIRS=new HashMap<>();
    static {
        for(String[] row:ItemTaxonomy.readRows("setup-layout-tables.tsv",4)) TABLES.put(row[0],new Table(row));
        for(String[] row:ItemTaxonomy.readRows("setup-layout-fields.tsv",4)) {
            Table table=TABLES.get(row[0]); if(table!=null) table.fields.add(new Field(row));
        }
        for(String[] row:ItemTaxonomy.readRows("setup-inventory-previews.tsv",6)) {
            Table table=TABLES.get(row[0]);
            if(table!=null && table.kind.equals("inventory")) table.fields.add(new Field(new String[]{row[0],row[1],row[2],row[4]},true));
        }
        for(String[] row:ItemTaxonomy.readRows("setup-inventory-pairs.tsv",2)) INVENTORY_PAIRS.put(row[0],row[1]);
    }
    final String equipmentName,inventoryName;
    final String activity;
    final Map<Integer,List<Integer>> equipment;
    final Map<Integer,Integer> inventory;
    final Map<Integer,Field> inventoryExample;
    private SetupLoadout(String activity,String equipmentName,String inventoryName,Map<Integer,List<Integer>> equipment,Map<Integer,Integer> inventory,Map<Integer,Field> inventoryExample) {
        this.activity=activity;
        this.equipmentName=equipmentName;this.inventoryName=inventoryName;
        this.equipment=equipment;this.inventory=inventory;this.inventoryExample=inventoryExample;
    }
    static boolean inventoryTable(ActivitySetups.Setup setup) { Table table=TABLES.get(setup.id);return table!=null && table.kind.equals("inventory"); }
    private static boolean ready(ItemCatalogueIndex.Item item) { return item!=null && !ItemVariantState.needsActivityReview(item.fact); }
    private static boolean inventoryReady(ActivitySetups.Setup setup,ItemCatalogueIndex.Item item) {
        return ready(item) && SetupItemRequirements.reviewReason(setup.id,item.fact).isEmpty();
    }
    private static boolean equipmentReady(ActivitySetups.Setup setup,ItemCatalogueIndex.Item item) {
        return inventoryReady(setup,item) && !ItemVariantState.needsRankReview(item.fact,setup.activity,setup.label);
    }
    static SetupLoadout build(List<ActivitySetups.Setup> matched,Map<Integer,ItemCatalogueIndex.Item> owned,Set<Integer> visible,String inventoryContext)
    {
        ActivitySetups.Setup gear=null; int best=-1;
        for(ActivitySetups.Setup setup:matched) {
            Table table=TABLES.get(setup.id); if(table==null || !table.kind.contains("equipment")) continue;
            Set<Integer> slots=new HashSet<>(),available=new HashSet<>();
            for(Field field:table.fields) if(field.slot()>=0) {
                slots.add(field.slot());
                if(field.ids.stream().anyMatch(id->visible.contains(id) && equipmentReady(setup,owned.get(id)) && owned.get(id).slot==field.slot())) available.add(field.slot());
            }
            // A boss-phase weapon list is not a complete equipment guide.
            if(slots.size()<3) continue;
            int score=available.size()*100+(table.kind.equals("recommended equipment")?10:0);
            if(score>best) { gear=setup;best=score; }
        }
        ActivitySetups.Setup anchor=gear;
        if(anchor==null) for(ActivitySetups.Setup setup:matched) if(inventoryTable(setup)) { anchor=setup;break; }
        if(anchor==null) return null;
        Table table=TABLES.get(anchor.id);
        Map<Integer,List<Integer>> equipment=new LinkedHashMap<>();
        List<Field> fields=gear==null?new ArrayList<>():new ArrayList<>(table.fields); fields.sort(Comparator.comparingInt(Field::order));
        for(Field field:fields) {
            int slot=field.slot(); if(slot<0) continue;
            // Conditional alternatives remain below the equipment diagram.
            if(!field.unconditional()) continue;
            for(int id:field.ids) {
                ItemCatalogueIndex.Item item=owned.get(id);
                if(!visible.contains(id) || !equipmentReady(gear,item) || item.slot!=slot) continue;
                List<Integer> options=equipment.computeIfAbsent(slot,k->new ArrayList<>());
                if(!options.contains(id)) options.add(id);
            }
        }
        ActivitySetups.Setup inventory=null;best=-1;int bestPreference=-1;
        for(ActivitySetups.Setup setup:ActivitySetups.forActivity(anchor.activity)) {
            if(!inventoryTable(setup)) continue;
            Table candidate=TABLES.get(setup.id);
            int score=0;Set<List<Integer>> distinct=new HashSet<>();
            for(Field field:candidate.fields) if(field.inventoryChoice() && distinct.add(field.ids)) {
                // Owning several colours/charge states of one switch must not
                // make an unrelated example appear more complete.
                int available=0;
                for(int id:field.ids) if(inventoryReady(setup,owned.get(id)))
                    available=Math.max(available,owned.get(id).slot>=0?20:1);
                score+=available;
            }
            boolean paired=gear!=null && setup.id.equals(INVENTORY_PAIRS.get(gear.id));
            boolean sameStyle=gear!=null && !table.style.isEmpty() && candidate.style.equalsIgnoreCase(table.style);
            boolean sameContext=sameStyle && !table.context.isEmpty() && candidate.context.equalsIgnoreCase(table.context);
            // Different methods can reuse labels such as "Best in slot".
            // Prefer the source pairing/context before comparing owned items.
            int preference=setup.id.equals(inventoryContext)?5:paired?4:sameContext?3:sameStyle?2:matched.contains(setup)?1:0;
            if(preference>bestPreference || preference==bestPreference && score>best)
            { inventory=setup;best=score;bestPreference=preference; }
        }
        Map<Integer,Integer> inventoryItems=new TreeMap<>();
        Map<Integer,Field> inventoryExample=new TreeMap<>();
        if(inventory!=null) for(Field field:TABLES.get(inventory.id).fields) {
            int position=field.order()-1;
            if(!(field.name.matches("[0-9]+") || field.name.startsWith("inventory")) || position<0 || position>=28 || field.ids.isEmpty()) continue;
            inventoryExample.put(position,field);
            if(!field.inventoryChoice()) continue;
            for(int id:field.ids) if(inventoryReady(inventory,owned.get(id))) { inventoryItems.put(position,id);break; }
        }
        return new SetupLoadout(anchor.activity,gear==null?"":gear.activity+" / "+gear.label,inventory==null?"No inventory example":inventory.label,equipment,inventoryItems,inventoryExample);
    }
}

package com.windowmarkers;

import java.util.*;

/** Source-backed supply filters. Names alone never establish healing or ammunition compatibility. */
final class SupplySearch
{
    private static final Map<Integer,Food> FOODS=new HashMap<>();
    private static final Map<String,Set<Integer>> GROUPS=new LinkedHashMap<>();
    private static final Map<String,String> ALIASES=new HashMap<>();
    static {
        for(String[] row:ItemTaxonomy.readRows("food-search-facts.tsv",12)) FOODS.put(Integer.parseInt(row[0]),new Food(row));
        for(String[] row:ItemTaxonomy.readRows("supply-search-groups.tsv",3))
            GROUPS.computeIfAbsent(SearchText.normalize(row[2]),k->new HashSet<>()).add(Integer.parseInt(row[0].substring(2)));
        alias("blowpipe","toxic blowpipe","blazing blowpipe","bp");
        alias("twisted bow","tbow");alias("rune crossbow","rcb");alias("armadyl crossbow","acb");
        alias("zaryte crossbow","zcb");alias("dragon hunter crossbow","dhcb");
        alias("karil crossbow","karils crossbow","karils");
        alias("hunters crossbow","hunter crossbow");alias("hunters sunlight crossbow","sunlight crossbow","hunter sunlight crossbow");
        alias("comp ogre bow","composite ogre bow");alias("cannon","dwarf multicannon","multicannon");
        alias("eclipse atlatl","atlatl");alias("ballista","heavy ballista","light ballista");
        for(String bow:Arrays.asList("oak","willow","maple","yew","magic")) alias(bow+" bow",bow+" shortbow",bow+" longbow");
        alias("magic bow","magic shortbow i","magic shortbow","magic longbow");
        alias("prayer restore","prayer restoration","restore prayer");alias("stat restore","stat restoration","restore stats");
        alias("run energy","energy","run restoration");alias("aggression","aggro","goading");
        alias("poison cure","antipoison");alias("venom cure","antivenom","anti venom");
        alias("antifire","dragonfire","dragonfire protection");alias("special attack","spec","special restore");
    }
    private static void alias(String canonical,String... aliases) { for(String alias:aliases) ALIASES.put(alias,canonical); }
    static boolean foodQuery(String raw) {
        String text=" "+SearchText.normalize(raw)+" ";
        return text.contains(" food ") || text.contains(" foods ");
    }
    static final class Query {
        final Set<String> flags=new HashSet<>();
        final Set<Integer> ids=new HashSet<>();
        boolean food,raw; int minimum=-1;
        String explanation="";
    }
    static Query parse(String raw) {
        String text=SearchText.normalize(raw);
        if(foodQuery(raw)) {
            Query q=new Query();q.food=true;
            for(String word:text.split(" +")) {
                if(word.matches("[0-9]{1,3}")) {
                    if(q.minimum>=0) return null;
                    q.minimum=Integer.parseInt(word);continue;
                }
                switch(word) {
                    case "food":case "foods":case "cooked":case "ready":case "to":case "eat":case "eating":case "healing":case "hp":case "bite":case "bites":case "only":case "cooking":case "inputs":case "area":break;
                    case "raw":case "uncooked":q.raw=true;break;
                    case "fast":case "combo":case "instant":case "delayed":case "multi":case "unrestricted":q.flags.add(word);break;
                    case "overheal":case "overhealing":q.flags.add("overheal");break;
                    case "wilderness":case "blighted":case "restricted":q.flags.add("restricted");break;
                    default:return null;
                }
            }
            if(q.raw) q.ids.addAll(GROUPS.getOrDefault("raw food cooking inputs",Collections.emptySet()));
            return q;
        }
        String kind=text.matches(".*\\b(?:potion|potions)\\b.*")?"potions":text.matches(".*\\b(?:ammo|ammunition)\\b.*")?"ammo":"";
        if(kind.isEmpty()) return null;
        String terms=text.replaceAll("\\b(?:potion|potions|ammo|ammunition|for)\\b"," ").replaceAll(" +"," ").trim();
        terms=ALIASES.getOrDefault(terms,terms);
        if(kind.equals("potions") && Arrays.asList("attack","strength","defence","defense","magic","ranged","agility","fishing","hunter").contains(terms))
            terms=(terms.equals("defense")?"defence":terms)+" boost";
        Query q=new Query();String key=kind+" "+terms;
        // A weapon that uses charges must not fuzzily acquire ammo from a similarly named bow.
        if(kind.equals("ammo") && Arrays.asList("bowfa","bow of faerdhinen","crystal bow","craws bow","webweaver bow").contains(terms)) {
            q.explanation="This weapon uses charges, not interchangeable ammunition. Check its charging requirements.";return q;
        }
        if(kind.equals("potions") && terms.equals("prayer")) {
            q.ids.addAll(GROUPS.getOrDefault("potions prayer restore",Collections.emptySet()));
            q.ids.addAll(GROUPS.getOrDefault("potions prayer regeneration",Collections.emptySet()));
        } else if(GROUPS.containsKey(key)) q.ids.addAll(GROUPS.get(key));
        else return null;
        q.explanation=kind.equals("ammo")?"Compatible ammunition for "+terms+". Weapon, Slayer and area requirements still apply.":"Potion effect: "+terms+". Strength, duration and side effects vary; this is not an activity recommendation.";
        return q;
    }
    static ItemCatalogueIndex.Result find(Query query,Collection<ItemCatalogueIndex.Item> items,int hitpoints) {
        List<ItemCatalogueIndex.Item> selected=new ArrayList<>();Map<Integer,ItemCatalogueIndex.Rank> notes=new HashMap<>();
        int hp=Math.max(1,Math.min(99,hitpoints));
        for(ItemCatalogueIndex.Item item:items) {
            String note=query.explanation;
            if(query.food && !query.raw) {
                Food food=FOODS.get(item.id);
                if(food==null || !food.name.equalsIgnoreCase(item.name) || !food.accepts(query,hp)) continue;
                note=food.explanation(hp);
            } else {
                if(!query.ids.contains(item.id)) continue;
                if(item.name.toLowerCase(Locale.ROOT).startsWith("blighted ")) note+=" Blighted: area restrictions apply.";
                if(query.raw) {
                    // Uncooked ingredients have no ready-to-eat healing value.
                    if(query.minimum>=0 || !query.flags.isEmpty()) continue;
                    note="Raw cooking input; prepare it before eating.";
                }
            }
            selected.add(item);notes.put(item.id,new ItemCatalogueIndex.Rank(0,note));
        }
        selected.sort(Comparator.comparing((ItemCatalogueIndex.Item item)->item.name,String.CASE_INSENSITIVE_ORDER).thenComparingInt(item->item.id));
        return new ItemCatalogueIndex.Result(selected,notes,false);
    }
    private static final class Food {
        final String name,formula;final int instant,delayed;final boolean multi,fast,combo,overheal,restricted;
        Food(String[] row) {
            name=row[1];instant=Integer.parseInt(row[2]);delayed=Integer.parseInt(row[3]);formula=row[4];
            multi=row[5].equals("1");fast=row[6].equals("1");combo=row[7].equals("1");overheal=row[8].equals("1");restricted=row[9].equals("1");
        }
        int immediate(int hp) {
            switch(formula) {
                case "anglerfish":return hp/10+2*(hp/25)+5*(hp/93)+2;
                case "strawberry":return 1+hp*6/100;
                case "watermelon":return 1+hp/20;
                case "sweetcorn":return 1+hp/10;
                default:return instant;
            }
        }
        boolean accepts(Query q,int hp) {
            if(q.flags.contains("fast")&&!fast || q.flags.contains("combo")&&!combo || q.flags.contains("multi")&&!multi
                || q.flags.contains("overheal")&&!overheal || q.flags.contains("delayed")&&delayed==0
                || q.flags.contains("instant")&&delayed>0 || q.flags.contains("restricted")&&!restricted
                || q.flags.contains("unrestricted")&&restricted) return false;
            if(q.minimum<0)return true;
            if(formula.equals("unknown") || formula.equals("random")) return false;
            return immediate(hp)+delayed>=q.minimum;
        }
        String explanation(int hp) {
            String heal=formula.equals("unknown")?"Healing varies; check the item's requirements":formula.equals("random")?"Unreliable healing; excluded from healing thresholds":
                immediate(hp)+" HP immediately"+(delayed>0?" + "+delayed+" delayed HP (pending hunter-food healing can be replaced)":"")+" per bite";
            if(!Arrays.asList("fixed","range","random","unknown").contains(formula))heal+=" at your base "+hp+" Hitpoints";
            if(formula.equals("range"))heal+=" (minimum; the actual amount varies)";
            return heal+"."+(multi?" Multiple bites per item; thresholds use one bite.":"")+(combo?" Combo-eating food.":"")
                +(fast?" Non-standard attack/eating delay.":"")+(overheal?" Can overheal; PvP restrictions apply.":"")
                +(restricted?" Blighted: Wilderness/PvP-world restrictions apply.":"");
        }
    }
}

package com.windowmarkers;

import java.awt.*;

/** The same guide tiers, colours and labels in the bank and GE. */
final class TierPresentation
{
    static String ordinal(int tier) { return tier==1?"1st":tier==2?"2nd":tier==3?"3rd":""; }
    static String key(WindowMarkersConfig config) {
        StringBuilder text=new StringBuilder("<html>Guide tiers: ");
        for(int i=1;i<=3;i++) {
            if(i>1) text.append(" · ");
            text.append("<font color='#").append(String.format("%06x",colour(config,i).getRGB()&0xffffff)).append("'>").append(ordinal(i)).append("</font>");
        }
        return text.append("</html>").toString();
    }
    static Color colour(WindowMarkersConfig config,int tier) {
        return tier==1?config.geFirstColour():tier==2?config.geSecondColour():config.geThirdColour();
    }
    static ItemCatalogueIndex.Rank merge(ItemCatalogueIndex.Rank a,ItemCatalogueIndex.Rank b) {
        if(a.tier==b.tier && a.role.equals(b.role)) return a;
        return new ItemCatalogueIndex.Rank(0,"Different selected guide roles or requirements; select a single setup to see its tier.");
    }
    static void draw(Graphics2D g,Rectangle grid,int tier,WindowMarkersConfig config) {
        if(tier<1 || tier>3) return;
        Color colour=colour(config,tier);
        g.setStroke(new BasicStroke(2)); BorderRenderer.plain(g,grid,colour);
        g.setFont(new Font("Arial",Font.BOLD,9));
        String text=ordinal(tier); FontMetrics fm=g.getFontMetrics();
        int width=fm.stringWidth(text)+4,height=fm.getHeight();
        int x=grid.x+grid.width-width,y=grid.y+grid.height-height;
        g.setColor(new Color(15,15,15,220));g.fillRoundRect(x,y,width,height,3,3);
        g.setColor(colour);g.drawRoundRect(x,y,width-1,height-1,3,3);
        g.setColor(Color.WHITE);g.drawString(text,x+2,y+fm.getAscent());
    }
}

package com.windowmarkers;

import java.util.*;

/** Bundled, audited Wiki item identities and useful roles. Does not imply activity eligibility. */
final class WikiCatalogue
{
    static final class Entry
    {
        final String facet, group;
        Entry(String facet,String group) { this.facet=facet; this.group=group; }
    }
    private static final Map<String,List<Entry>> INDEX=new HashMap<>();
    private static final Map<String,List<Entry>> CATEGORY_SUPPLEMENT=new HashMap<>();
    private static final Map<String,List<Entry>> ROLE_EXCLUSIONS=new HashMap<>();
    private static final Set<Integer> AMBIGUOUS_NAMES=new HashSet<>();
    private static final Set<Integer> EXCLUDED_IDENTITIES=new HashSet<>();
    static
    {
        for (String[] row : ItemTaxonomy.readRows("item-catalogue.tsv",3))
        { INDEX.computeIfAbsent(row[0],k -> new ArrayList<>()).add(new Entry(row[1],row[2])); }
        for (String[] row:ItemTaxonomy.readRows("ambiguous-item-names.tsv",1))
        { AMBIGUOUS_NAMES.add(Integer.parseInt(row[0])); }
        for (String[] row:ItemTaxonomy.readRows("catalogue-identity-exclusions.tsv",1))
        { EXCLUDED_IDENTITIES.add(Integer.parseInt(row[0])); }
        // Exact-ID Wiki category evidence supplements organizational roles only.
        // Raid recommendations and ranked alternatives use their own reviewed resources.
        for (String resource : new String[]{"wiki-category-supplement.tsv","combat-equivalence-categories.tsv","wiki-recipe-roles.tsv","wiki-role-updates.tsv","supply-search-groups.tsv"})
        for (String[] row : ItemTaxonomy.readRows(resource,3))
        {
            if (!row[0].matches("I:[0-9]+")) { throw new IllegalStateException("Wiki category requires an exact item ID"); }
            List<Entry> entries=CATEGORY_SUPPLEMENT.computeIfAbsent(row[0],k -> new ArrayList<>());
            if (entries.stream().noneMatch(e -> e.facet.equals(row[1]) && e.group.equals(row[2])))
            { entries.add(new Entry(row[1],row[2])); }
        }
        for (String[] row : ItemTaxonomy.readRows("catalogue-role-exclusions.tsv",3))
        {
            if (!row[0].matches("I:[0-9]+")) { throw new IllegalStateException("Role correction requires an exact item ID"); }
            ROLE_EXCLUSIONS.computeIfAbsent(row[0],k -> new ArrayList<>()).add(new Entry(row[1],row[2]));
        }
    }
    static List<Entry> entries(AutoCategories.Item item)
    {
        if (EXCLUDED_IDENTITIES.contains(item.id)) { return Collections.emptyList(); }
        List<Entry> result=INDEX.get("I:"+item.id);
        boolean nameSafe=!AMBIGUOUS_NAMES.contains(item.id);
        if (result==null && nameSafe) { result=INDEX.get("N:"+item.name); }
        if (result==null && nameSafe) { result=INDEX.get("N:"+ItemTaxonomy.baseName(item.name)); }
        if (result==null && nameSafe && item.name.matches(".*\\s*\\([1-8]\\)$"))
        {
            List<Entry> charged=INDEX.get("N:"+item.name.replaceFirst("\\s*\\([1-8]\\)$",""));
            if (charged!=null && charged.stream().anyMatch(e -> e.facet.equals("travel"))) { result=charged; }
        }
        List<Entry> supplement=CATEGORY_SUPPLEMENT.get("I:"+item.id);
        List<Entry> exclusions=ROLE_EXCLUSIONS.get("I:"+item.id);
        if (supplement==null && exclusions==null) { return result==null ? Collections.emptyList() : result; }
        // Preserve reviewed name aliases when adding an exact-ID category record.
        List<Entry> combined=result==null ? new ArrayList<>() : new ArrayList<>(result);
        if (supplement!=null) for (Entry entry:supplement)
        {
            if (combined.stream().noneMatch(e -> e.facet.equals(entry.facet) && e.group.equals(entry.group)))
            { combined.add(entry); }
        }
        // Correct only the reviewed identity and role, including a name fallback
        // from a different item with the same display name. Shared indexes stay intact.
        if (exclusions!=null)
        { combined.removeIf(e -> exclusions.stream().anyMatch(x -> x.facet.equals(e.facet) && x.group.equals(e.group))); }
        return combined;
    }
    static boolean hasFacet(AutoCategories.Item item,String facet)
    { return entries(item).stream().anyMatch(e -> e.facet.equals(facet)); }

    static Set<String> groups()
    {
        Set<String> groups=new TreeSet<>();
        for(Map<String,List<Entry>> index:Arrays.asList(INDEX,CATEGORY_SUPPLEMENT))
            for(List<Entry> entries:index.values()) for(Entry entry:entries) groups.add(entry.group);
        return groups;
    }

    static String category(AutoCategories.Item item,AutoCategories.Preset preset)
    {
        if (preset==AutoCategories.Preset.FOOD_AND_POTIONS && !hasFacet(item,"supply") && !hasFacet(item,"restricted") && !item.action("Eat") && !item.action("Drink")) { return null; }
        Entry best=null;
        for (Entry entry : entries(item))
        {
            if (!accepts(preset,entry)) { continue; }
            if (best==null || priority(entry)<priority(best) || (priority(entry)==priority(best) && entry.group.compareTo(best.group)<0)) { best=entry; }
        }
        return best==null ? null : best.group;
    }
    private static int priority(Entry e)
    {
        switch (e.facet)
        {
            case "outfit": return 0;
            case "restricted": return 1;
            case "boost": return 2;
            case "skilling": return e.group.contains("materials") || e.group.contains("ingredients") || e.group.contains("products")
                || e.group.endsWith("recipe inputs") || e.group.endsWith("guild access") || e.group.endsWith("pouch protection") || e.group.endsWith("warm clothing") ? 9 : 3;
            case "travel": return 4;
            case "combat": return e.group.startsWith("Prayer") ? 7 : 5;
            case "supply": return 6;
            case "utility": return 8;
            case "quest": return 10;
            case "clue": return 11;
            default: return 12;
        }
    }
    private static boolean accepts(AutoCategories.Preset p,Entry e)
    {
        switch (p)
        {
            case ALL_CATEGORIES: case BROAD_TYPES: return true;
            case SKILLING: return e.facet.equals("outfit") || e.facet.equals("skilling") || (e.facet.equals("boost") && !e.group.startsWith("Combat"));
            case SKILLING_OUTFITS: return e.facet.equals("outfit");
            case COMBAT_GROUPS: return e.facet.equals("combat") || (e.facet.equals("boost") && e.group.startsWith("Combat"));
            case FOOD_AND_POTIONS: return e.facet.equals("supply") || e.facet.equals("boost") || e.facet.equals("restricted");
            case TRAVEL_AND_UTILITY: return e.facet.equals("travel") || e.facet.equals("utility");
            case QUESTS_AND_CLUES: return e.facet.equals("quest") || e.facet.equals("clue");
            case COSMETICS: return e.facet.equals("cosmetic");
            default: return false;
        }
    }
    static String source(AutoCategories.Preset preset)
    {
        switch (preset)
        {
            case SKILLING: case SKILLING_OUTFITS: return "https://oldschool.runescape.wiki/w/Skilling_equipment";
            case FOOD_AND_POTIONS: return "https://oldschool.runescape.wiki/w/Potions";
            case TRAVEL_AND_UTILITY: return "https://oldschool.runescape.wiki/w/Container_items";
            case QUESTS_AND_CLUES: return "https://oldschool.runescape.wiki/w/Quest_items";
            case COSMETICS: return "https://oldschool.runescape.wiki/w/Clothes";
            case ALL_CATEGORIES: case BROAD_TYPES: case COMBAT_GROUPS: return "https://oldschool.runescape.wiki/w/Equipment";
            default: return RaidRecommendations.source(preset);
        }
    }
}

