package com.windowmarkers;

import java.awt.*;
import java.awt.event.ActionEvent;
import java.util.*;
import java.util.List;
import javax.swing.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CategoryWorkflowTest
{
    private AutoCategories.Item item(int id,String name) { return new AutoCategories.Item(id,name,false,null,0,0,0); }

    @Test public void lookupClickAddsColoredSecondaryGroupEvenWhenItemIsAlreadyGrouped() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            AutoCategories.Item empty=item(5331,"Watering can");
            String category=WikiCatalogue.entries(empty).stream().filter(e -> e.group.startsWith("Farming")).findFirst().get().group;
            String membership="Category: "+ItemVariantState.annotate(category,empty);
            ItemLookupPanel lookup=new ItemLookupPanel(Collections.singletonList(empty.name),Collections.singletonList(Collections.singleton(membership)));
            lookup.list.setSelectedIndex(0); lookup.send.doClick();
            assertEquals(membership,lookup.membership);
            List<BankCatalogue.Choice> targets=BankCatalogue.targets(lookup.membership,Collections.emptyList());
            assertEquals(1,targets.size());
            Map<String,List<AutoCategories.Item>> groups=BankCatalogue.categoryGroups(targets.get(0),Collections.singletonList(empty));
            Marker first=new Marker(0,0,48,36); first.label="My tools"; first.linkedItemIds=new int[]{5331}; first.borderArgb=Color.CYAN.getRGB();
            List<Marker> markers=new ArrayList<>(Collections.singletonList(first));
            CategoryGroups.Result added=CategoryGroups.add(markers,groups,"All classifications",true,Color.YELLOW,250);
            assertEquals(1,added.added); assertEquals(2,markers.size());
            Marker fresh=added.selected.get(0);
            assertArrayEquals(new int[]{5331},fresh.linkedItemIds);
            assertNotEquals(first.borderArgb,fresh.borderArgb);
            assertEquals(fresh.borderArgb & 0xffffff,fresh.backgroundArgb & 0xffffff);
            assertEquals(65,new Color(fresh.backgroundArgb,true).getAlpha());
            assertTrue(fresh.category.contains("fill before watering"));
            MarkerLegend legend=new MarkerLegend(m -> {},m -> {});
            List<MarkerLegend.Entry> rows=Arrays.asList(new MarkerLegend.Entry(first,first.label,Color.CYAN),
                new MarkerLegend.Entry(fresh,fresh.label,new Color(fresh.borderArgb,true)));
            legend.replace(rows); legend.search.setText("unrelated search"); legend.showGroups(added.selected);
            assertEquals(Collections.singletonList(fresh),legend.selected());
            assertEquals(fresh.borderArgb.intValue(),legend.list.getSelectedValue().color.getRGB());
            int color=fresh.borderArgb;
            CategoryGroups.Result repeated=CategoryGroups.add(markers,groups,"All classifications",true,Color.YELLOW,250);
            assertEquals(0,repeated.added); assertEquals(1,repeated.existing); assertSame(fresh,repeated.selected.get(0));
            assertEquals(color,fresh.borderArgb.intValue()); legend.close();
        });
    }
    @Test public void bulkDefaultKeepsExistingGroupsAndReportsSkippedMemberships() {
        Marker existing=new Marker(0,0,48,36); existing.linkedItemIds=new int[]{385}; existing.borderArgb=Color.BLUE.getRGB();
        List<Marker> markers=new ArrayList<>(Collections.singletonList(existing));
        CategoryGroups.Result result=CategoryGroups.add(markers,Collections.singletonMap("Food",Collections.singletonList(item(385,"Shark"))),"Broad",false,Color.RED,250);
        assertEquals(0,result.added); assertEquals(1,result.skipped); assertEquals(1,markers.size());
    }
    @Test public void presetMembershipKeepsActivityScopeAndReviewRowsCannotBeAdded() throws Exception {
        String membership="Preset: "+AutoCategories.Preset.THEATRE_OF_BLOOD+" / ToB Magic equipment";
        var target=BankCatalogue.targets(membership,Collections.emptyList()).get(0);
        assertEquals(AutoCategories.Preset.THEATRE_OF_BLOOD,target.presetScope);
        assertEquals("ToB Magic equipment",target.name);
        assertTrue(BankCatalogue.targets("Review: Unknown identity",Collections.emptyList()).isEmpty());
        SwingUtilities.invokeAndWait(() -> {
            ItemLookupPanel lookup=new ItemLookupPanel(Collections.singletonList("Unknown"),Collections.singletonList(Collections.singleton("Review: Unknown identity")));
            lookup.list.setSelectedIndex(0); assertFalse(lookup.send.isEnabled()); assertTrue(lookup.highlight.isEnabled());
        });
    }
    @Test public void lookupResolvesExactSavedCustomAndWikiTargetsWithoutFuzzyGuessing() {
        Marker marker=new Marker(0,0,48,36); marker.label="My food / potions"; marker.linkedItemIds=new int[]{385};
        CustomPresets.Preset preset=new CustomPresets.Preset(); preset.name="Raids"; preset.groups.add(marker);
        CustomPresets custom=new CustomPresets(); custom.presets.add(preset);
        List<BankCatalogue.Choice> all=BankCatalogue.choices(Collections.emptyList(),Collections.singletonList(marker),custom);
        assertSame(marker,BankCatalogue.targets("Saved group: "+marker.label,all).get(0).value);
        var target=BankCatalogue.targets("Custom preset: Raids / "+marker.label,all).get(0);
        assertSame(preset,target.value); assertEquals(marker.label,target.customGroup);
        ActivitySetups.Setup setup=ActivitySetups.all().iterator().next();
        assertTrue(BankCatalogue.targets("Wiki setup: "+setup.activity+" / "+setup.label+" — state needs review",all).stream().anyMatch(c -> c.value==setup));
        assertTrue(BankCatalogue.targets("Saved group: My fod / potions",all).isEmpty());
    }
    @Test public void legendSuggestionEnterPassesTheActualChoiceRatherThanSearchingItsNameAgain() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            BankCatalogue.Choice choice=new BankCatalogue.Choice(BankCatalogue.Kind.CATEGORY,"My exact category","My exact category");
            BankCatalogue.Choice[] chosen={null};
            MarkerLegend legend=new MarkerLegend(m -> {},m -> {},new MarkerLegend.Actions() {
                public void edit(Marker m) {} public void items(Marker m) {} public void delete(List<Marker> m) {}
                public void clear(List<Marker> m) {} public void browse(String q) { fail("Must not reopen a fuzzy search"); }
                public void choose(BankCatalogue.Choice c) { chosen[0]=c; }
                public void inspect() {} public void reorder(List<Marker> a,List<Marker> b,int i) {} public void transform(Marker m,boolean r) {}
            });
            legend.catalogue(Collections.singletonList(choice)); legend.search.setText("exact"); legend.filter();
            JList<?> suggestions=findSuggestions(legend); assertNotNull(suggestions); suggestions.setSelectedIndex(0);
            suggestions.getActionMap().get("browse").actionPerformed(new ActionEvent(suggestions,0,"browse"));
            assertSame(choice,chosen[0]); legend.close();
        });
    }
    private JList<?> findSuggestions(Container c) {
        for(Component child:c.getComponents()) {
            if(child instanceof JList && ((JList<?>)child).getModel().getSize()>0
                && ((JList<?>)child).getModel().getElementAt(0) instanceof BankCatalogue.Choice) return (JList<?>)child;
            if(child instanceof Container) { JList<?> found=findSuggestions((Container)child); if(found!=null) return found; }
        }
        return null;
    }
}

package com.windowmarkers;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CombatEquivalenceTest
{
    private AutoCategories.Item item(int id,String name)
    { return new AutoCategories.Item(id,name,true,null,0,0,0); }
    private boolean has(Map<String,List<AutoCategories.Item>> groups,int id)
    { return groups.values().stream().flatMap(Collection::stream).anyMatch(i -> i.id==id); }
    private final AutoCategories.Preset[] raids={AutoCategories.Preset.CHAMBERS_OF_XERIC,
        AutoCategories.Preset.THEATRE_OF_BLOOD,AutoCategories.Preset.TOMBS_OF_AMASCUT};

    @Test public void combatEquivalentsAreIncludedAcrossRaidPresets()
    {
        AutoCategories.Item[] items={item(13329,"Fire max cape"),item(21285,"Infernal max cape"),
            item(27374,"Masori assembler"),item(27363,"Masori assembler max cape"),
            item(21898,"Assembler max cape"),item(28902,"Dizana's max cape"),
            item(21776,"Imbued Saradomin max cape"),item(34633,"Imbued ancient cape"),item(34625,"Imbued ancient max cape")};
        for (AutoCategories.Preset raid:raids)
        {
            Map<String,List<AutoCategories.Item>> groups=AutoCategories.suggest(raid,Arrays.asList(items));
            for(AutoCategories.Item i:items) { assertTrue(raid+": "+i.name,has(groups,i.id)); }
        }
    }
    @Test public void equalityDoesNotTransferCluesGodProtectionOrAllMaxPerks()
    {
        assertFalse(ItemTaxonomy.matches(item(13329,"Fire max cape"),"fire cape"));
        assertFalse(CombatEquivalence.matches(item(13329,"Fire max cape"),"max cape"));
        assertFalse(CombatEquivalence.matches(item(34633,"Imbued ancient cape"),"imbued saradomin cape"));
        assertFalse(CombatEquivalence.matches(item(21186,"Fire max cape"),"fire cape")); // animation ID
        List<WikiCatalogue.Entry> roles=WikiCatalogue.entries(item(13329,"Fire max cape"));
        assertTrue(roles.stream().anyMatch(e -> e.group.equals("Runecraft — pouch protection")));
        assertFalse(roles.stream().anyMatch(e -> e.group.contains("Crafting Guild teleport")));
        assertFalse(CombatEquivalence.matches(item(13280,"Max cape"),"ava's assembler")); // account unlock not inferred
    }
    @Test public void ornamentsResolveToTheirActualCombatVersion()
    {
        assertTrue(CombatEquivalence.matches(item(27253,"Elidinis' ward (or)"),"elidinis' ward (f)"));
        assertFalse(CombatEquivalence.matches(item(27253,"Elidinis' ward (or)"),"elidinis' ward"));
        assertTrue(CombatEquivalence.matches(item(29804,"Amulet of rancour (s)"),"amulet of rancour"));
        assertTrue(CombatEquivalence.matches(item(28025,"Dragon dagger (p++)(cr)"),"dragon dagger(p++)"));
        assertFalse(CombatEquivalence.matches(item(28025,"Dragon dagger (p++)(cr)"),"dragon dagger"));
        assertTrue(ItemVariantState.needsActivityReview(item(33332,"Iban's staff (u) (o)")));
        assertTrue(ItemVariantState.needsActivityReview(item(33316,"Uncharged toxic trident (o)")));
    }
    @Test public void productionInputsDoNotOverruleEquipmentOrSupplyRoles()
    {
        assertTrue(WikiCatalogue.entries(item(1933,"Pot of flour")).stream()
            .anyMatch(e -> e.facet.equals("skilling") && e.group.equals("Cooking — recipe inputs")));
        assertTrue(WikiCatalogue.entries(item(946,"Knife")).stream()
            .anyMatch(e -> e.facet.equals("skilling") && e.group.endsWith(" — tools")));
        assertTrue(WikiCatalogue.entries(item(227,"Vial of water")).stream()
            .anyMatch(e -> e.group.equals("Herblore — recipe inputs")));
        assertFalse(WikiCatalogue.category(item(6570,"Fire cape"),AutoCategories.Preset.BROAD_TYPES).contains("recipe inputs"));
    }
    @Test public void usableOrnamentedUpgradeParticipatesWithoutCollapsingEqualVariants()
    {
        AutoCategories.Preset raid=AutoCategories.Preset.CHAMBERS_OF_XERIC;
        Map<String,List<AutoCategories.Item>> groups=AutoCategories.suggest(raid,Arrays.asList(
            item(25985,"Elidinis' ward"),item(27251,"Elidinis' ward (f)"),item(27253,"Elidinis' ward (or)")));
        RaidGearFilter.filter(raid,groups,new int[]{99,99,99,99,99,99,99},true,true,new HashMap<>());
        assertFalse(has(groups,25985));assertTrue(has(groups,27251));assertTrue(has(groups,27253));
        groups=AutoCategories.suggest(raid,Arrays.asList(item(25985,"Elidinis' ward"),item(27253,"Elidinis' ward (or)")));
        RaidGearFilter.filter(raid,groups,new int[]{99,99,99,99,99,99,99},true,true,new HashMap<>());
        assertFalse(has(groups,25985));assertTrue(has(groups,27253));
    }
    @Test public void containersAndCountersKeepTheirDifferentFunctions()
    {
        assertTrue(ItemVariantState.needsActivityReview(item(1831,"Waterskin(0)")));
        assertFalse(ItemVariantState.needsActivityReview(item(1823,"Waterskin(4)")));
        assertFalse(ItemVariantState.needsActivityReview(item(33386,"Open gem pouch")));
        assertFalse(ItemVariantState.needsActivityReview(item(25584,"Open fish barrel")));
        assertTrue(ItemVariantState.needsActivityReview(item(33218,"Knapsack")));
        assertTrue(ItemVariantState.needsActivityReview(item(33431,"Trinket of vengeance (1)")));
        assertTrue(ItemVariantState.needsActivityReview(item(20784,"Dragon claws"))); // LMS copy shares a real weapon's name
        assertFalse(ItemVariantState.needsActivityReview(item(13652,"Dragon claws")));
    }
    @Test public void gloryStatesSeparateCombatMiningAndClueUses()
    {
        assertFalse(WikiCatalogue.entries(item(1704,"Amulet of glory")).stream().anyMatch(e -> e.group.startsWith("Mining")));
        assertTrue(WikiCatalogue.entries(item(1712,"Amulet of glory(4)")).stream().anyMatch(e -> e.group.equals("Mining — glory gem benefit")));
        assertTrue(WikiCatalogue.entries(item(10354,"Amulet of glory (t4)")).stream().anyMatch(e -> e.group.equals("Mining — glory gem benefit")));
        assertTrue(WikiCatalogue.entries(item(19707,"Amulet of eternal glory")).stream().anyMatch(e -> e.group.equals("Mining — glory gem benefit")));
        assertFalse(ItemVariantState.needsActivityReview(item(1704,"Amulet of glory")));
        assertTrue(CombatEquivalence.matches(item(19707,"Amulet of eternal glory"),"amulet of glory"));
        assertFalse(ItemTaxonomy.matches(item(10362,"Amulet of glory (t)"),"amulet of glory"));
    }
    @Test public void sharedDisplayNamesDoNotShareUnrelatedWikiRoles()
    {
        assertTrue(WikiCatalogue.entries(item(25615,"Large water container")).isEmpty());
        assertTrue(WikiCatalogue.entries(item(21539,"Heat-proof vessel")).isEmpty());
        assertFalse(WikiCatalogue.entries(item(617,"Coins")).stream().anyMatch(e -> e.group.toLowerCase(Locale.ROOT).contains("currenc")));
        assertTrue(WikiCatalogue.entries(item(617,"Coins")).stream().anyMatch(e -> e.group.contains("Shilo")));
        assertTrue(CombatEquivalence.matches(item(19641,"Black slayer helmet (i)"),"slayer helmet (i)"));
        assertFalse(CombatEquivalence.matches(item(19641,"Black slayer helmet (i)"),"slayer helmet"));
        assertFalse(CombatEquivalence.matches(item(2603,"Adamant kiteshield (t)"),"adamant kiteshield"));
    }
    @Test public void unusableVariantsRemainUncheckedAndCannotReplaceUsableGear()
    {
        for (AutoCategories.Preset raid:raids)
        {
            Map<String,List<AutoCategories.Item>> groups=AutoCategories.suggest(raid,Arrays.asList(
                item(20447,"Fire max cape (broken)"),item(21289,"Infernal max cape (broken)"),item(6570,"Fire cape")));
            assertTrue(groups.entrySet().stream().filter(e -> has(Collections.singletonMap(e.getKey(),e.getValue()),21289))
                .allMatch(e -> !RaidRecommendations.defaultSelected(e.getKey())));
            RaidGearFilter.filter(raid,groups,new int[]{99,99,99,99,99,99,99},true,true,new HashMap<>());
            assertTrue(has(groups,6570));
        }
    }
    @Test public void equalVariantsStayAndMaxReplacementNeedsAllSkills()
    {
        for (AutoCategories.Preset raid:raids)
        {
            List<AutoCategories.Item> capes=Arrays.asList(item(6570,"Fire cape"),item(13329,"Fire max cape"),
                item(21285,"Infernal max cape"));
            Map<String,List<AutoCategories.Item>> groups=AutoCategories.suggest(raid,capes);
            RaidGearFilter.filter(raid,groups,new int[]{99,99,99,99,99,99,99},true,false,new HashMap<>());
            assertTrue(has(groups,6570)); assertTrue(has(groups,13329));
            RaidGearFilter.filter(raid,groups,new int[]{99,99,99,99,99,99,99},true,true,new HashMap<>());
            assertFalse(has(groups,6570)); assertFalse(has(groups,13329)); assertTrue(has(groups,21285));
            groups=AutoCategories.suggest(raid,Arrays.asList(item(21295,"Infernal cape"),item(21285,"Infernal max cape")));
            RaidGearFilter.filter(raid,groups,new int[]{99,99,99,99,99,99,99},true,true,new HashMap<>());
            assertTrue(has(groups,21295)); assertTrue(has(groups,21285));
        }
    }
}

package com.windowmarkers;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class EditingTest
{
    @Test public void historySupportsUndoRedoBranchingAndBoundedMemory()
    {
        MarkerHistory h=new MarkerHistory(); h.reset("a"); h.record("b"); h.record("c");
        assertEquals("b",h.undo()); assertEquals("a",h.undo()); assertNull(h.undo());
        assertEquals("b",h.redo()); h.record("d"); assertNull(h.redo()); assertEquals("b",h.undo());
        h.reset("0"); for(int i=1;i<=60;i++) { h.record(""+i); }
        for(int i=59;i>=10;i--) { assertEquals(""+i,h.undo()); }
        assertNull(h.undo());
    }
    @Test public void moveAndResizeClampToWindowWithoutLosingMinimumSize()
    {
        Rectangle bounds=new Rectangle(100,100,300,300), original=new Rectangle(150,150,60,70);
        assertEquals(new Rectangle(340,330,60,70),WindowMarkersPlugin.transformRectangle(original,new Point(160,160),new Point(900,900),false,bounds));
        assertEquals(new Rectangle(150,150,250,250),WindowMarkersPlugin.transformRectangle(original,new Point(160,160),new Point(900,900),true,bounds));
        assertEquals(new Rectangle(150,150,16,16),WindowMarkersPlugin.transformRectangle(original,new Point(160,160),new Point(100,100),true,bounds));
    }
    @Test public void labelsCanBePlacedOutsideTheRegion()
    {
        BufferedImage image=new BufferedImage(100,100,2); Graphics2D g=image.createGraphics();
        try
        {
            Marker m=new Marker(0,0,50,50); Rectangle r=new Rectangle(20,20,50,50);
            m.labelPlacement=Marker.LabelPlacement.ABOVE;
            assertTrue(WindowMarkersPlugin.labelBaseline(m,r,g.getFontMetrics())<20);
            m.labelPlacement=Marker.LabelPlacement.BELOW;
            assertTrue(WindowMarkersPlugin.labelBaseline(m,r,g.getFontMetrics())>70);
        } finally { g.dispose(); }
    }
    @Test public void catalogKeepsExistingDefaultKeyAndRepairsUnknownSelection()
    {
